203.     ///
204.     /// # Parameters
205.     ///
206.     /// - `region`: Physical memory region whose frames should be booked.
207.     ///
208.     /// # Returns
209.     ///
210.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
211.     ///
212.     #[verus_spec(result =>
213.         requires
214.             old(self).inv(),
215.             region.inv(),
216.         ensures
217.             self.inv(),
218.             ({
219.                 let start_frame_number = region@.start / spec_page_size();
220.                 let end_frame_number = (region@.start + region@.size) / spec_page_size();
221.                 let frame_numbers = vstd::set_lib::set_int_range(start_frame_number, end_frame_number);
222.                 let frames = frame_numbers.map(|i: int| i * spec_page_size());
223.                 match result {
224.                     Ok(()) => {
225.                         &&& frames.subset_of(old(self)@.free_frames)
226.                         &&& self@ == old(self)@.spec_alloc_range(frames)
227.                     },
228.                     Err(_) => {
229.                         &&& self@ == old(self)@
230.                         &&& !frames.subset_of(old(self)@.free_frames)
231.                     },
232.                 }
233.             }),
234.     )]
235.     fn alloc_range(
236.         &mut self,
237.         region: &TruncatedMemoryRegion<PhysicalAddress>,
238.     ) -> Result<(), Error> {
239.         let start_frame_number: usize = region.start().into_frame_number().into_raw_value();
240.         // VERUS REWRITE: replaced `start + size/FRAME_SIZE - 1` and `..=` (inclusive range)
241.         // with exclusive upper bound. RangeInclusive<usize> lacks ForLoopGhostIteratorNew.
242.         let num_frames: usize = region.size() / mem::FRAME_SIZE;
243.         let end_frame_number: usize = start_frame_number + num_frames;
244. 
245.         // When nightly-performance-optimizations is off, verify that every frame index in the
246.         // range is covered by the sparse bitmap. SparseBitmap::test() returns Ok(false) for
247.         // uncovered indices, which would incorrectly appear as "free" and pass the check below,
248.         // only to fail on set(). With the feature enabled this check is elided because
249.         // PhysicalAddress construction already guarantees valid physical addresses.
250.         #[cfg(not(feature = "nightly-performance-optimizations"))]
251.         for index in start_frame_number..end_frame_number {
252.             if self.bitmap.find_chunk(index).is_none() {
253.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
254.                 let reason: &str = "frame index not covered by any bitmap chunk";
255.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
256.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
257.             }
258.         }
259. 
260.         // Check if all frames in the range are free.
261.         for index in start_frame_number..end_frame_number {
262.             match self.bitmap.test(index) {
263.                 Ok(false) => continue,
264.                 Ok(true) => {
265.                     let conflicting_addr: usize = index * mem::FRAME_SIZE;
266.                     let region_start: usize = region.start().into_raw_value();
267.                     let region_end: usize = region_start.saturating_add(region.size());
268.                     let reason: &str = "frame is already allocated";
269.                     error!(
270.                         "{} (frame={:#010x}, region_start={:#010x}, region_end={:#010x})",
271.                         reason, conflicting_addr, region_start, region_end
272.                     );
273.                     return Err(Error::new(ErrorCode::OutOfMemory, reason));
274.                 },
275.                 Err(err) => return Err(err),
276.             }
277.         }
278. 
279.         // Book all frames in the range.
280.         for index in start_frame_number..end_frame_number {
281.             if let Err(error) = self.bitmap.set(index) {
282.                 error!("{error:?} (region={region:?})");
283.                 return Err(error);
284.             }
285.         }
286. 
287.         Ok(())
288.     }
289. }
